events.title:
"[user]\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$analysisRoot = (Resolve-Path -LiteralPath output/analysis).Path
$taskRoot = (Get-Location).Path
if ($analysisRoot -ne (Join-Path $taskRoot '"'output\\analysis')) { throw 'Unexpected cleanup directory' }
"'$analysisKeep = @('"'verify.py','prototype-transcript.json','review-transcript.json','assets-sheet.jpg')
Get-ChildItem -LiteralPath "'$analysisRoot -File | Where-Object { $_.Name -notin $analysisKeep -and $_.Name -notmatch '"'"'^(tour-sheet-[0-3]|review-sheet-[0-4]|located-sheet-[0-8])'"\\.jpg"'$'"' } | ForEach-Object { Remove-Item -LiteralPath "'$_.FullName }
Get-ChildItem -LiteralPath output/site -File | Select-Object Name,Length'
